uint16_t stun_set_channel_bind_request(stun_buffer *buf, const ioa_addr *peer_addr, uint16_t channel_number) {

  return stun_set_channel_bind_request_str(buf->buf, &(buf->len), peer_addr, channel_number);
}

int stun_get_command_message_len_str(const uint8_t *buf, size_t len) {
  if (len < STUN_HEADER_LENGTH) {
    return -1;
  }

  /* Validate the size the buffer claims to be */
  const size_t bufLen = (size_t)(turn_read_u16(buf + 2) + STUN_HEADER_LENGTH);
  if (bufLen > len) {
    return -1;
  }

  return bufLen;
}

bool stun_attr_add_str(uint8_t *buf, size_t *len, uint16_t attr, const uint8_t *avalue, int alen) {
  if (alen < 0) {
    alen = 0;
  }
  uint8_t tmp[1];
  if (!avalue) {
    alen = 0;
    avalue = tmp;
  }
  const int clen = stun_get_command_message_len_str(buf, *len);
  int newlen = clen + 4 + alen;
  const int newlenrem4 = newlen & 0x00000003;
  int paddinglen = 0;
  if (newlenrem4) {
    paddinglen = 4 - newlenrem4;
    newlen = newlen + paddinglen;
  }

  if (newlen >= MAX_STUN_MESSAGE_SIZE) {
    return false;
  }

  uint8_t *attr_start = buf + clen;

  stun_set_command_message_len_str(buf, newlen);
  *len = newlen;

  turn_write_u16(attr_start, attr);
  turn_write_u16(attr_start + 2, (uint16_t)alen);
  if (alen > 0) {
    memcpy(attr_start + 4, avalue, alen);
  }

  // Write 0 padding to not leak data
  memset(attr_start + 4 + alen, 0, paddinglen);

  return true;
}

static inline void turn_write_u16(void *field, uint16_t v) {
  const uint16_t raw = nswap16(v);
  memcpy(field, &raw, sizeof(raw));
}

